-- Rollback (handmatig): herzet content naar de fase 3b-tekst uit migratie 20260814094405.
INSERT INTO public.doc_articles (doc_level, category_id, slug, context_path, title, excerpt, content, sort_order)
VALUES (
  'tenant',
  'a0000001-0000-0000-0000-000000000001',
  'ticket-product-datums',
  '/admin/products',
  'Ticket-product aanmaken en datums beheren',
  'Verkoop tickets voor evenementen: maak een ticketproduct aan en beheer datums, capaciteit, status en de slimme datum-acties.',
  '<h2>Ticket-product aanmaken</h2><p>Ga naar <strong>Producten</strong> en klik op <strong>Nieuw product</strong>. Kies bij het producttype de kaart <strong>Ticket / Event</strong>. Verzending en voorraadbeheer worden dan automatisch uitgeschakeld: een ticket is een dienst, de beschikbaarheid regel je via de capaciteit per datum.</p><p>Vul verder de gewone productgegevens in (naam, prijs, beschrijving, afbeeldingen) en klik op <strong>Opslaan</strong>.</p><h2>Datums beheren</h2><p>Na het opslaan verschijnt op het productscherm de sectie <strong>Events &amp; Datums</strong>. Klik op <strong>Datum toevoegen</strong> en vul in:</p><ul><li><strong>Datum</strong> — de dag waarop het evenement doorgaat.</li><li><strong>Starttijd</strong> — standaard 21:00, aanpasbaar.</li><li><strong>Capaciteit</strong> — het maximum aantal deelnemers voor die datum.</li><li><strong>Minimum deelnemers</strong> — vanaf hoeveel inschrijvingen het evenement doorgaat (0 als er geen minimum is).</li><li><strong>Locatie</strong> en <strong>Verzamelpunt</strong> — optioneel, handig om mee te geven aan je deelnemers.</li></ul><h2>Status per datum</h2><p>Elke datum heeft een status. Vier daarvan kies je zelf:</p><ul><li><strong>Gepland</strong> — de datum staat vast maar is nog niet bevestigd.</li><li><strong>Bevestigd</strong> — het evenement gaat door.</li><li><strong>Geannuleerd</strong> — het evenement gaat niet door.</li><li><strong>Afgerond</strong> — het evenement is voorbij.</li></ul><p>Twee statussen worden alleen door de acties hieronder gezet en staan daarom niet in de keuzelijst: <strong>Overgeslagen</strong> en <strong>Samengevoegd</strong>.</p><h2>Meerdere datums in een keer plannen</h2><p>Klik op <strong>Plan meerdere datums</strong>. Kies een startdatum, het aantal weken en de weekdag (standaard de weekdag van je startdatum, dus bijvoorbeeld "elke zaterdag"). Stel de gedeelde starttijd, capaciteit en minimum deelnemers in.</p><p>Je krijgt een voorbeeldlijst van alle datums met een vinkje per datum, allemaal aangevinkt. Vink uit wat niet past — bijvoorbeeld een feestdag — en klik op <strong>Aanmaken</strong>. Datums die al bestaan voor dit product worden automatisch overgeslagen; dat wordt onder de lijst gemeld.</p><h2>Een datum verplaatsen</h2><p>Klik op het kalender-icoon naast een datum en kies de nieuwe dag. Alleen de datum zelf verandert. Kopers van al verkochte tickets worden in deze versie nog niet automatisch verwittigd; die automatische communicatie volgt in een latere update.</p><h2>Een datum overslaan</h2><p>Met <strong>Overslaan</strong> markeer je een datum als niet doorgaand zonder hem te verwijderen. De rij blijft staan, doorgestreept en met de badge <strong>Overgeslagen</strong>. Met <strong>Terugzetten</strong> maak je dit in een klik ongedaan: de datum wordt weer <strong>Gepland</strong>. Zo verlies je nooit gegevens.</p><h2>Datums samenvoegen</h2><p>Gaan twee datums beter samen door? Klik op <strong>Datums samenvoegen</strong>. Er verschijnen vinkvakjes per datum: selecteer er twee of meer. Klik daarna op <strong>Samenvoegen</strong> en kies welke datum blijft doorgaan — dat is de datum waar iedereen naartoe gaat.</p><p>De overige datums krijgen de status <strong>Samengevoegd</strong> en tonen een pijl naar de winnende datum. Samenvoegen kan alleen voor datums die gepland, bevestigd of overgeslagen zijn — niet voor geannuleerde, afgeronde of al samengevoegde datums. Ook hier volgt de automatische communicatie naar kopers in een latere update.</p><h2>Bewerken en verwijderen</h2><p>Klik op het potloodicoon naast een datum om de gegevens aan te passen, of op het prullenbakicoon om de datum te verwijderen. Verwijderen vraagt om een bevestiging en kan niet ongedaan gemaakt worden — gebruik bij twijfel liever <strong>Overslaan</strong>.</p>',
  3
)
